<?php
require_once __DIR__.'/../../includes/layout.php';require_login();check_csrf();$u=current_user();$error='';$recovery=[];
if($_SERVER['REQUEST_METHOD']==='POST')try {
    $action=(string)($_POST['action']??'');$password=(string)($_POST['password']??'');
    if(!password_verify($password,$u['password_hash']))throw new InvalidArgumentException('Your current password is incorrect.');
    if($action==='begin') {
        if(scalar('SELECT COUNT(*) FROM account_mfa WHERE user_id=?',[$u['id']]))throw new InvalidArgumentException('MFA is already enabled.');
        $_SESSION['mfa_enrollment']=['secret'=>base32_encode_secret(random_bytes(20)),'expires'=>time()+600];
    }elseif($action==='confirm') {
        $pending=$_SESSION['mfa_enrollment']??null;if(!$pending||$pending['expires']<time())throw new InvalidArgumentException('Setup expired. Start again.');
        $step=mfa_step($pending['secret'],trim((string)($_POST['code']??'')));if($step===null)throw new InvalidArgumentException('Enter the current six-digit code from your authenticator app.');
        for($i=0;$i<10;$i++)$recovery[]=strtoupper(bin2hex(random_bytes(12)));
        $encrypted=mfa_encrypt($pending['secret']);
        db()->beginTransaction();try{db()->prepare('INSERT INTO account_mfa(user_id,secret,recovery_hashes,last_step) VALUES(?,?,?,?)')->execute([$u['id'],$encrypted,json_encode(array_map(fn($c)=>hash('sha256',$c),$recovery)),$step]);db()->prepare('UPDATE users SET auth_version=auth_version+1 WHERE id=?')->execute([$u['id']]);log_activity($u['id'],'MFA enabled','Authenticator enabled; other sessions revoked.');db()->commit();}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();throw$e;}
        $_SESSION['auth_version']=(int)$u['auth_version']+1;unset($_SESSION['mfa_enrollment']);session_regenerate_id(true);
    }elseif($action==='regenerate') {
        if(!mfa_verify((int)$u['id'],(string)($_POST['code']??'')))throw new InvalidArgumentException('Provide a valid authenticator or unused recovery code.');
        for($i=0;$i<10;$i++)$recovery[]=strtoupper(bin2hex(random_bytes(12)));
        db()->prepare('UPDATE account_mfa SET recovery_hashes=? WHERE user_id=?')->execute([json_encode(array_map(fn($c)=>hash('sha256',$c),$recovery)),$u['id']]);log_activity($u['id'],'MFA recovery codes replaced','Previous recovery codes invalidated.');
    }elseif($action==='disable') {
        if(campus_mode()==='production'&&campus_staff())throw new InvalidArgumentException('Administrators require MFA in production.');
        if(!mfa_verify((int)$u['id'],(string)($_POST['code']??'')))throw new InvalidArgumentException('Provide a valid authenticator or unused recovery code.');
        db()->prepare('DELETE FROM account_mfa WHERE user_id=?')->execute([$u['id']]);db()->prepare('UPDATE users SET auth_version=auth_version+1 WHERE id=?')->execute([$u['id']]);$_SESSION['auth_version']=(int)$u['auth_version']+1;session_regenerate_id(true);log_activity($u['id'],'MFA disabled','Other sessions revoked.');set_flash('success','MFA disabled for this demo account.');redirect('security.php');
    }else throw new InvalidArgumentException('Choose a valid security action.');
}catch(InvalidArgumentException $e){$error=$e->getMessage();}catch(PDOException $e){$error='MFA setup has changed. Reload the page.';}
$enabled=(bool)scalar('SELECT COUNT(*) FROM account_mfa WHERE user_id=?',[$u['id']]);$pending=$_SESSION['mfa_enrollment']??null;render_header('Account security'); ?>
<div class="page-title"><div><span class="eyebrow">YOUR ACCOUNT</span><h1>Account security</h1><p>Protect sign-ins with an authenticator app and one-time recovery codes.</p></div></div><?php if($error): ?><div class="alert alert-danger" role="alert"><?= e($error) ?></div><?php endif; ?>
<?php if($recovery): ?><section class="panel"><h2>Save your recovery codes now</h2><p>Each code works once. These codes will not be displayed again. Store them privately, separately from your password.</p><ul class="campus-code"><?php foreach($recovery as $code): ?><li data-recovery-code><?= e($code) ?></li><?php endforeach; ?></ul></section><?php endif; ?>
<section class="panel"><h2><?= $enabled?'Authenticator enabled':'Set up two-step sign-in' ?></h2><?php if(!$enabled&&$pending&&$pending['expires']>=time()): ?><p>Add a time-based account to your authenticator app using this setup key. Use six digits and a 30-second interval.</p><code class="campus-code d-block" data-mfa-secret><?= e($pending['secret']) ?></code><p class="mt-3">Account label: <?= e($u['username']) ?> · ICAS Campus</p><form method="post" class="campus-form"><?= csrf_field() ?><input type="hidden" name="action" value="confirm"><label>Current password<input type="password" name="password" class="form-control" autocomplete="current-password" required></label><label>Current six-digit code<input name="code" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" autocomplete="one-time-code" class="form-control" required></label><button class="btn btn-primary">Confirm authenticator</button></form><?php elseif(!$enabled): ?><p>MFA is optional for the free demo and required for administrators in production. Use an authenticator app that supports standard time-based codes.</p><form method="post" class="campus-form"><?= csrf_field() ?><input type="hidden" name="action" value="begin"><label>Current password<input type="password" name="password" class="form-control" autocomplete="current-password" required></label><button class="btn btn-primary">Start authenticator setup</button></form><?php else: ?><p>Password sign-in now requires an authenticator code or one unused recovery code. Older sessions were revoked when MFA was enabled.</p><details><summary>Replace recovery codes</summary><form method="post" class="campus-form"><?= csrf_field() ?><input type="hidden" name="action" value="regenerate"><label>Current password<input type="password" name="password" autocomplete="current-password" class="form-control" required></label><label>Authenticator / recovery code<input name="code" maxlength="40" autocomplete="one-time-code" class="form-control" required></label><button class="btn btn-outline-primary">Generate new recovery codes</button></form></details><?php if(!(campus_mode()==='production'&&campus_staff())): ?><details><summary>Disable authenticator</summary><form method="post" class="campus-form"><?= csrf_field() ?><input type="hidden" name="action" value="disable"><label>Current password<input type="password" name="password" class="form-control" autocomplete="current-password" required></label><label>Authenticator / recovery code<input name="code" maxlength="40" autocomplete="one-time-code" class="form-control" required></label><button class="btn btn-outline-danger">Disable MFA</button></form></details><?php endif;endif; ?></section><?php render_footer(); ?>
